TLM.f("Tempora/Quadp3-6",{"officium":"Sabbato post Cineres","rule":["no Gloria","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;","Super populum"],"ruleInherited":["no Gloria","Credo","Prefatio=Trinitate","Suffr=Maria2;Sanctorum,Ecclesiæ;;"],"fallback":"Tempora/Quadp3-0","from":{"GradualeF":"Tempora/Quadp3-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 29:11"},{"k":"text","la":"Audívit Dóminus, et misértus est mihi: Dóminus factus est adjútor meus."},{"k":"ref","la":"Ps 29:2"},{"k":"text","la":"Exaltábo te, Dómine, quóniam suscepísti me: nec delectásti inimícos meos super me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Audívit Dóminus, et misértus est mihi: Dóminus factus est adjútor meus."}],"Oratio":[{"k":"text","la":"Adésto, Dómine, supplicatiónibus nostris: et concéde; ut hoc sollémne jejúnium, quod animábus corporibúsque curándis salúbriter institútum est, devóto servítio celebrémus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ."},{"k":"ref","la":"Isa 58:9-14"},{"k":"text","la":"Hæc dicit Dóminus Deus: Si abstúleris de médio tui caténam, et desíeris exténdere dígitum, et loqui quod non prodest. Cum effúderis esuriénti ánimam tuam, et ánimam afflíctam repléveris, oriétur in ténebris lux tua, et ténebræ tuæ erunt sicut merídies. Et réquiem tibi dabit Dóminus semper, et implébit splendóribus ánimam tuam, et ossa tua liberábit, et eris quasi hortus irríguus, et sicut fons aquárum, cujus non defícient aquæ. Et ædificabúntur in te desérta sæculórum: fundaménta generatiónis et generatiónis suscitábis: et vocáberis ædificátor sépium, avértens sémitas in quiétem. Si avérteris a sábbato pedem tuum, fácere voluntátem tuam in die sancto meo, et vocáveris sábbatum delicátum, et sanctum Dómini gloriósum, et glorificáveris eum, dum non facis vias tuas, et non invénitur volúntas tua, ut loquáris sermónem: tunc delectáberis super Dómino: et sustóllam te super altitúdines terræ, et cibábo te hereditáte Jacob, patris tui. Os enim Dómini locútum est."}],"Graduale":[{"k":"ref","la":"Ps 26:4"},{"k":"text","la":"Unam pétii a Dómino, hanc requíram, ut inhábitem in domo Dómini,"},{"k":"text","la":"Ut vídeam voluptátem Dómini, et prótegar a templo sancto ejus.","mark":"V"}],"GradualeF":[{"k":"ref","la":"Ps 76:15; 76:16"},{"k":"text","la":"Tu es Deus qui facis mirabília solus: notam fecísti in géntibus virtútem tuam."},{"k":"text","la":"Liberásti in bráchio tuo pópulum tuum, fílios Israël et Joseph.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum."},{"k":"ref","la":"Marc 6:47-56"},{"k":"text","la":"In illo témpore: Cum sero esset, erat navis in médio mari, et Jesus solus in terra. Et videns discípulos suos laborántes in remigándo - erat enim ventus contrárius eis, - et circa quartam vigíliam noctis venit ad eos ámbulans supra mare: et volébat præteríre eos. At illi, ut vidérunt eum ambulántem supra mare, putavérunt phantásma esse, et exclamavérunt. Omnes enim vidérunt eum, et conturbáti sunt. Et statim locútus est cum eis, et dixit eis: Confídite, ego sum, nolíte timére. Et ascéndit ad illos in navim, et cessávit ventus. Et plus magis intra se stupébant: non enim intellexérunt de pánibus: erat enim cor eórum obcæcátum. Et cum transfretássent, venérunt in terram Genésareth, et applicuérunt. Cumque egréssi essent de navi, contínuo cognovérunt eum: et percurréntes univérsam regiónem illam, cœpérunt in grabátis eos, qui se male habébant, circumférre ubi audiébant eum esse. Et quocúmque introíbat, in vicos vel in villas aut civitátes, in platéis ponébant infírmos, et deprecabántur eum, ut vel fímbriam vestiménti ejus tángerent: et quotquot tangébant eum, salvi fiébant."}],"Offertorium":[{"k":"ref","la":"Ps 118:154 ; 118:125"},{"k":"text","la":"Dómine, vivífica me secúndum elóquium tuum: ut sciam testimónia tua."}],"Secreta":[{"k":"text","la":"Súscipe, Dómine, sacrifícium, cujus te voluísti dignánter immolatióne placári: præsta, quǽsumus; ut, hujus operatióne mundáti, beneplácitum tibi nostræ mentis offerámus afféctum."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 2:11-12"},{"k":"text","la":"Servite Dómino in timóre, et exsultáte ei cum tremóre: apprehéndite disciplínam, ne pereátis de via justa."}],"Postcommunio":[{"k":"text","la":"Cœléstis vitæ múnere vegetáti, quǽsumus, Dómine: ut, quod est nobis in præsénti vita mystérium, fiat æternitátis auxílium."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Fidéles tui, Deus, per tua dona firméntur: ut éadem et percipiéndo requírant, et quæréndo sine fine percípiant."},{"k":"macro","name":"Per Dominum"}]},"hr":{"b35396e89743b495":{"t":"Ps 29, 11, Ps 29, 2\n(Ps 29, 11) Gospodin me je čuo i smilovao se meni. Gospodin je postao moj pomoćnik. (Ps 29, 2) Veličat ću te, Gospodine, jer si me odabrao, nisi dao da se moji neprijatelji raduju nada mnom.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 29, 11) Gospodin me je čuo i smilovao se meni. Gospodin je postao moj pomoćnik.","kn":"(P,s. 29, 11)., Cuo je Gospodin ismilovao se\"^ meni. Gospodin je postao spašiteij moj (Bs. .129' 2) Hvalim Te, Gospodine, jer ši me .uzdigao i nisi 'dopustio da se neprijatelji , moji vesele nada mnom. Slava Ocu . . . Cuo je Gospodin ...","knRef":"Kniewald 1942, str. 104–105 (snimka 53) (OCR)"},"f7a0ad57dc9bd42e":{"t":"<i>Pomolimo se</i>.\nMilostiv budi, Gospodine, našim molitvama i daj da ovaj svečani post koji je spasonosno ustanovljen za zdravlje duše i tijela izvršavamo odanom pokornošću.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, naše molbe i dopusti, da vjerno izvršimo ovaj svečani post, koji je spa- Bonosno ustanovljen za ozdravljenje duše i tijela, po G. n.","knRef":"Kniewald 1942, str. 106–107 (snimka 54) (OCR)"},"5920cbd38389df99":{"t":"Iz 58, 9-14\nČitanje Izaije proroka. Ovo govori Gospodin Bog: Ako zbaciš sa sebe okove, prestaneš pružati prst i govoriti zlo, pa otvoriš svojeg srce gladnome i nasitiš nevoljnika, zasjat će i u mraku tvoje svjetlo, nestat će tame i bit će kao podne. Gospodin će ti osigurati trajan mir, prosvijetlit će ti dušu i okrijepiti tvoje kosti, bit ćeš kao natopljen vrt i kao izvor kojemu ne ponestaje vode. Po pustim mjestima podizat ćeš zgrade, utvrdit ćeš temelje do posljednjih naraštaja koji će te zvati da si graditelj ograda i donosilac mira na putovima. Ako ne oskvrneš subote i ne sagriješiš u dan meni posvećen, i ako budeš poštovao subotu kao dan radosti i posvećen na Gospodnju slavu i ako ga budeš cijenio i ne budeš zašao na krive putove, te ne budeš vršio svoje volje i ne budeš govorio zla. Gospodin će biti tvoja slast i uzvisit će te nad zemaljske veličine i obdari će te baštinom tvog oca Jakova. Gospodin je to rekao.","kn":"Čitanje Izaije Proroka. (Iz. 58, 9-14). Ovo govori Gospodin Bog; Ako zbaciš sa sebe okove, ■ i prestaneš pružati /prst, i govoriti, što nije dobro; a raistvoriš srce svoje gladnome, i nasitiš dušu nevoljnu; tada će zasjati u mraku svjetlost tvoja, i tmine će tvoje biti kao podne. I Gospodin će ti dati mir za vazda, i dušu će tvoju prosvijetliti, i kosti će tvoje okrijeipiti, i bit ćeš vrt zaliven, kao vrelo, kojemu ne ponestaje vode. I ti ćeš podizati zgrade po mjestima od davnine pustim, i utvrdit ćeš temelje od koljena na koljeno, i prozvat ćeš se: graditelj plotova, i donosilac mira na putovima. Ako odstupiš nogom svojom od subote, da ne činiš, što je tebi drago na moj sveti dan, i ako budeš držao subotu kao dan. radosti, i za dan sveti posvećen Gospodinu: i budeš ga slavio ne hodeći svojim putovima, i ne čineći svoju volju, i ne govoreći^ zlo: tada ćeš se nasladiti u Gos/piodinu: i uzdignut ću te nad visine zemaljske, i branit ću te nasljedstvom Jakova, oca tvojega. Jer usta Gospodnja rekoše.","knRef":"Kniewald 1942, str. 106–107 (snimka 54) (OCR)"},"67101eda04fcfe91":{"t":"Ps 26, 4\nJedno samo molim od Gospodina, samo ovo tražim: da stanujem u domu Gospodnjem, da gledam ljupkost Gospodnju da se sklonim u sveti hram njegov.","kn":"(Ps. 26, 4). Za jedno samo. molim, Gospodine i samo to tražim, da stanujem u domu Gospodnjemu u sve dane moga života. Da vidim Gospodine i da posjetim njegov hram.","knRef":"Kniewald 1942, str. 774–775 (snimka 388) (OCR)"},"10d3b3198cdb596d":{"t":"Mk 6, 47-56\nSlijedi sveto Evanđelje po Marku. U ono vrijeme kad se spustila večer, lađa je bila na pučini, a sam je Isus bio na kopnu. Tad vidje kako se njegovi učenici muče veslajući jer je puhao protivan vjetar. Oko četvrte noćne straže idući po moru dođe do njih i htjede ih mimoići. A kad ga oni opaze, da hoda po moru, pomisliše da je sablast i povikaše, jer ga svi vidješe i preplašiše se. On im odmah prozbori i reče: Smirite se, nemojte se bojati! Tada uđe k njima u lađu, i vjetar prestane. Oni su se to više začudili, jer još nisu bili shvatili čuda s kruhom. Njihovo je srce bilo zaslijepljeno. Kad su preplovili more, pristanu u zemlji Genezaret. A kad su izašli iz lađe, ljudi ga prepoznaše, pa prođu onim krajevima i gdje su čuli da je on, donosili su na ležajima bolesnike. I u koje je god selo, grad ili naselje ulazio, postavljali su bolesnike na putove i molili ga da se dotaknu barem okrajka njegove haljine, te su ozdravljali svi koji su ga se dotakli.","kn":"t Slijedi sv. evanđelje po Marku (6, 47-56). U ono vrijeme: Kad bi u veče, bijaše lađa nasred mora, a Isus sam na kraju. I vidje učenike svoje, gdje se trude vozeći (jer im bijaše vjetar protivan) i oko četvrte noćne straže dođe k njima hodeći po moru: i htio ih je mimoići. A oni, kad ga vidješe, gdje ide po moru, mišijahu, da je utvajra i prepadoše se. I odmah stade govoriti s njima, i reče im; Umirite se, ja sam, nemojte se bojati. I uđe k njima u lađu, i vjetar prestane. I još se više u sebi čuđato, jer još ne razumješe o hljebovima, bijaše bo srce njihovo zaslijepljeno. I kad se prevezoše, dođoše u zemlju Genezaretsku, i pristadoše uz kraj. I kad iziđoše iz lađe, odmah ga poznaše: i ophodeći svu onu zemlju, počeše na posteljama donositi bolesnike, gdje su čuli, da je on, I kud god iđaše u varoši, ili u sela, ili u gradove, stavljahu bolesnike po ulicama i moljahu ga, da; se barem skuta cd haljine njegove dotaknu: i ozdravljahu, koji ga se god doticahu.","knRef":"Kniewald 1942, str. 106–107 (snimka 54) (OCR)"},"e377320db8d2b6d1":{"t":"Ps 118, 154 i 125\nOživi me, Gospodine, po riječi tvojoj, utisni mi u srce naredbe svoje.","kn":"(Ps. 118, 154, 125). Gospodine, oživi me, !po riječi svojoj, da spoznam svjedočanstva Tvoja.","knRef":"Kniewald 1942, str. 106–107 (snimka 54) (OCR)"},"c41df56ce19dd826":{"t":"Primi, Gospodine, žrtvu kojom si se blagonaklono htio pomiriti, i daj nam, molimo te, da očišćeni njezinim djelovanjem prinesemo tebi prijatan osjećaj svoje duše.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, žrtvu, kojom si se milostivo dao pomiriti i podaj, molimo, da. njezinom djelatnošću očišćeni, prinesemo Tebi prijatne osjećaje naše duše, po G. n.","knRef":"Kniewald 1942, str. 108–109 (snimka 55) (OCR)"},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo 1 spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože. koji tjelesnim postom obuzdavaš opačine, duh dižeš, daješ krepost i nagrade,' po Kristu, Gospodinu našemu; po kojem veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te 1 nebeske Red i čin sv. mise moći i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"0f5686ae25f2ecdf":{"t":"Ps 2, 11-12\nSlužite Gospodinu u strahopoštovanju, kličite mu u predanju duše, prihvatite njegovu nauku da ne skrenete s pravog puta."},"16560c47d5170e4a":{"t":"<i>Pomolimo se</i>.\nNahranjeni darom nebeskog života, molimo, Gospodine, da nam ono što nam je u sadašnjem životu tajna, bude pomoć za vječnost.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši dar nebeskog života, molimo te, Gospodine, da nam svetotajstvo, što ga . primlamo u sadašnjem životu, postane porhoću za vječnost, PO G. n.","knRef":"Kniewald 1942, str. 108–109 (snimka 55) (OCR)"},"b37f7e3a173da092":{"t":"<i>Pomolimo se</i>.\nVjernici tvoji, Bože, neka se tvojim darovima učvrste, da ih primajući traže i tražeći ih uvijek primaju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Bože, da se Tvoji vjennici ovim darovima učvrste, te da ih i primajući traže i tražeći bez prestanka primaju, po G. n. I. K.","knRef":"Kniewald 1942, str. 90–91 (snimka 46) (OCR)"}}});
